import heapq


def _dependency_solver(data, name_order, preference):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        versions = [row for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + versions)

    best_vector = None
    best_installation = None
    for selection in product(*choices):
        installed = {name: row for name, row in zip(names, selection)
                     if row is not None}
        if any(root not in installed or
               not bounds[0] <= installed[root]["version"] <= bounds[1]
               for root, bounds in data["roots"].items()):
            continue
        edges = {name: [] for name in installed}
        valid = True
        for name, row in installed.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = installed.get(dep["name"])
                if target is None or not dep["min"] <= target["version"] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(dep["name"])
            if not valid:
                break
        if not valid:
            continue
        visiting, finished = set(), set()
        def visit(node):
            if node in visiting:
                return False
            if node in finished:
                return True
            visiting.add(node)
            if any(not visit(other) for other in edges[node]):
                return False
            visiting.remove(node)
            finished.add(node)
            return True
        if not all(visit(node) for node in edges):
            continue
        vector = tuple(installed[n]["version"] if n in installed else -1
                       for n in names)
        if (best_vector is None or
            (vector > best_vector if preference == "maximum" else vector < best_vector)):
            best_vector = vector
            best_installation = {n: row["version"] for n, row in installed.items()}
    if best_installation is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_installation}


